mkuse!{use super :: context :: Context ;}
mkuse!{use super :: select :: { Operation , Selected } ;}
mkuse!{use crate :: ptr ;}
mkuse!{use crate :: sync :: Mutex ;}
mkuse!{use crate :: sync :: atomic :: { Atomic , AtomicBool , Ordering } ;}
mkitem!{mkstruct!{# [doc = " Represents a thread blocked on a specific channel operation."] pub (crate) struct Entry { # [doc = " The operation."] pub (crate) oper : Operation , # [doc = " Optional packet."] pub (crate) packet : * mut () , # [doc = " Context associated with the thread owning this operation."] pub (crate) cx : Context , }}}
mkitem!{mkstruct!{# [doc = " A queue of threads blocked on channel operations."] # [doc = ""] # [doc = " This data structure is used by threads to register blocking operations and get woken up once"] # [doc = " an operation becomes ready."] pub (crate) struct Waker { # [doc = " A list of select operations."] selectors : Vec < Entry > , # [doc = " A list of operations waiting to be ready."] observers : Vec < Entry > , }}}
mkitem!{mkimpl!{impl Waker { # [doc = " Creates a new `Waker`."] # [inline] pub (crate) fn new () -> Self { Waker { selectors : Vec :: new () , observers : Vec :: new () } } # [doc = " Registers a select operation."] # [inline] pub (crate) fn register (& mut self , oper : Operation , cx : & Context) { self . register_with_packet (oper , ptr :: null_mut () , cx) ; } # [doc = " Registers a select operation and a packet."] # [inline] pub (crate) fn register_with_packet (& mut self , oper : Operation , packet : * mut () , cx : & Context) { self . selectors . push (Entry { oper , packet , cx : cx . clone () }) ; } # [doc = " Unregisters a select operation."] # [inline] pub (crate) fn unregister (& mut self , oper : Operation) -> Option < Entry > { if let Some ((i , _)) = self . selectors . iter () . enumerate () . find (| & (_ , entry) | entry . oper == oper) { let entry = self . selectors . remove (i) ; Some (entry) } else { None } } # [doc = " Attempts to find another thread's entry, select the operation, and wake it up."] # [inline] pub (crate) fn try_select (& mut self) -> Option < Entry > { if self . selectors . is_empty () { None } else { let thread_id = current_thread_id () ; self . selectors . iter () . position (| selector | { selector . cx . thread_id () != thread_id && selector . cx . try_select (Selected :: Operation (selector . oper)) . is_ok () && { selector . cx . store_packet (selector . packet) ; selector . cx . unpark () ; true } }) . map (| pos | self . selectors . remove (pos)) } } # [doc = " Notifies all operations waiting to be ready."] # [inline] pub (crate) fn notify (& mut self) { for entry in self . observers . drain (..) { if entry . cx . try_select (Selected :: Operation (entry . oper)) . is_ok () { entry . cx . unpark () ; } } } # [doc = " Notifies all registered operations that the channel is disconnected."] # [inline] pub (crate) fn disconnect (& mut self) { for entry in self . selectors . iter () { if entry . cx . try_select (Selected :: Disconnected) . is_ok () { entry . cx . unpark () ; } } self . notify () ; } }}}
mkitem!{mkimpl!{impl Drop for Waker { # [inline] fn drop (& mut self) { debug_assert_eq ! (self . selectors . len () , 0) ; debug_assert_eq ! (self . observers . len () , 0) ; } }}}
mkitem!{mkstruct!{# [doc = " A waker that can be shared among threads without locking."] # [doc = ""] # [doc = " This is a simple wrapper around `Waker` that internally uses a mutex for synchronization."] pub (crate) struct SyncWaker { # [doc = " The inner `Waker`."] inner : Mutex < Waker > , # [doc = " `true` if the waker is empty."] is_empty : Atomic < bool > , }}}
mkitem!{mkimpl!{impl SyncWaker { # [doc = " Creates a new `SyncWaker`."] # [inline] pub (crate) fn new () -> Self { SyncWaker { inner : Mutex :: new (Waker :: new ()) , is_empty : AtomicBool :: new (true) } } # [doc = " Registers the current thread with an operation."] # [inline] pub (crate) fn register (& self , oper : Operation , cx : & Context) { let mut inner = self . inner . lock () . unwrap () ; inner . register (oper , cx) ; self . is_empty . store (inner . selectors . is_empty () && inner . observers . is_empty () , Ordering :: SeqCst) ; } # [doc = " Unregisters an operation previously registered by the current thread."] # [inline] pub (crate) fn unregister (& self , oper : Operation) -> Option < Entry > { let mut inner = self . inner . lock () . unwrap () ; let entry = inner . unregister (oper) ; self . is_empty . store (inner . selectors . is_empty () && inner . observers . is_empty () , Ordering :: SeqCst) ; entry } # [doc = " Attempts to find one thread (not the current one), select its operation, and wake it up."] # [inline] pub (crate) fn notify (& self) { if ! self . is_empty . load (Ordering :: SeqCst) { let mut inner = self . inner . lock () . unwrap () ; if ! self . is_empty . load (Ordering :: SeqCst) { inner . try_select () ; inner . notify () ; self . is_empty . store (inner . selectors . is_empty () && inner . observers . is_empty () , Ordering :: SeqCst ,) ; } } } # [doc = " Notifies all threads that the channel is disconnected."] # [inline] pub (crate) fn disconnect (& self) { let mut inner = self . inner . lock () . unwrap () ; inner . disconnect () ; self . is_empty . store (inner . selectors . is_empty () && inner . observers . is_empty () , Ordering :: SeqCst) ; } }}}
mkitem!{mkimpl!{impl Drop for SyncWaker { # [inline] fn drop (& mut self) { debug_assert ! (self . is_empty . load (Ordering :: SeqCst)) ; } }}}

macro_rules! current_thread_id_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function current_thread_id in module {}", module_path!());
    };
}

mkfn!{
    current_thread_id_introspect!();
    # [doc = " Returns a unique id for the current thread."] # [inline] pub fn current_thread_id () -> usize { thread_local ! { static DUMMY : u8 = const { 0 } } DUMMY . with (| x | (x as * const u8) . addr ()) }
}